import{A as e,H as t,P as n,_ as r,a as i,f as a,g as o,h as s,t as c,u as l}from"./chunks/plugin-vue_export-helper.I53torQa.js";var u=JSON.parse(`{"title":"昇腾 AI 硬件技术介绍——以 Ascend 910C 为主，兼述 Ascend 950","description":"","frontmatter":{"title":"昇腾 AI 硬件技术介绍——以 Ascend 910C 为主，兼述 Ascend 950","version":1,"updated":"2026-11-23T00:00:00.000Z","language":"zh-CN"},"headers":[],"relativePath":"ascend/architecture/昇腾硬件技术介绍_910C与950.md","filePath":"ascend/architecture/昇腾硬件技术介绍_910C与950.md","lastUpdated":1795411813000}`),d={name:`ascend/architecture/昇腾硬件技术介绍_910C与950.md`};function f(c,u,d,f,p,m){let h=n(`Mermaid`);return e(),a(`div`,null,[u[8]||=s(`<h1 id="昇腾-ai-硬件技术介绍" tabindex="-1">昇腾 AI 硬件技术介绍 <a class="header-anchor" href="#昇腾-ai-硬件技术介绍" aria-label="Permalink to “昇腾 AI 硬件技术介绍”">​</a></h1><p><strong>——以 Ascend 910C 为主，兼述 Ascend 950 系列</strong></p><blockquote><p><strong>文档日期：</strong> 2026 年 11 月 23 日<br><strong>适用读者：</strong> AI 基础设施规划人员、系统架构师、算法工程师、平台运维人员及技术管理人员<br><strong>内容范围：</strong> Ascend 910C 芯片及其服务器、超节点系统；Ascend 950PR/950DT 的技术演进与产品形态；昇腾软件栈、互联和部署要点。</p></blockquote><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to “1. 概述”">​</a></h2><p>昇腾（Ascend）是华为面向人工智能计算推出的处理器及计算平台系列。其硬件产品并非只有单颗 AI 芯片，还包括加速卡、AI 服务器、超节点（SuperPoD）以及更大规模的智算集群。Atlas 是华为基于昇腾处理器和基础软件构建的 AI 计算产品体系，覆盖训练、推理及行业 AI 应用场景。[1]</p><p>本文重点介绍 <strong>Ascend 910C</strong>。910C 是昇腾面向大规模训练和推理的重要一代产品，其关键价值不仅在于单芯片计算能力，更在于与鲲鹏 CPU、高速互联、统一内存编址、服务器和超节点技术协同形成系统级算力。以 Atlas 900 A3 SuperPoD 为例，系统最多支持 384 个 NPU 高速互联，官方公布的 FP16 峰值算力为 307.2/288.7 PFLOPS，并支持 48 TB 片上内存统一编址。[2]</p><p><strong>Ascend 950</strong> 是后续一代产品系列，包含面向推理 Prefill 和推荐场景的 <strong>950PR</strong>，以及面向推理 Decode 和训练场景的 <strong>950DT</strong>。相较 910C，950 系列的重要变化包括：新增 FP8、MXFP8、MXFP4、HiF8 等低精度格式；引入 SIMD/SIMT 双编程模型；提升向量计算能力；并将互联升级至灵衢 Unified Bus 2.0（UB 2.0）。[3][4]</p><h3 id="_1-1-关键结论" tabindex="-1">1.1 关键结论 <a class="header-anchor" href="#_1-1-关键结论" aria-label="Permalink to “1.1 关键结论”">​</a></h3><ul><li><strong>910C 的系统价值在于规模化协同。</strong> 单芯片算力、HBM 带宽、芯片间互联和集群通信必须结合起来评估，不能只看单卡峰值算力。</li><li><strong>910C 与 950 的互联代际不同。</strong> 910C 所在的第一代超节点通常采用灵衢 1.0/HCCS 体系；950 系列采用灵衢 2.0/UB 2.0，并引入 URMA、UB Memory 等内存语义。[5]</li><li><strong>950PR 与 950DT 并非简单的高低配。</strong> 两者针对不同工作负载优化：PR 偏 Prefill、推荐等计算密集型任务；DT 偏 Decode、训练等对内存带宽和互联要求更高的任务。[3]</li><li><strong>规格必须对应具体产品 SKU。</strong> 芯片规划值、芯片级参数、加速卡参数和整机/超节点参数并不等价；不同代际公开资料也存在更新或统计口径差异，采购与验收应以最终产品规格书和兼容性清单为准。</li></ul><h2 id="_2-基础概念与产品层级" tabindex="-1">2. 基础概念与产品层级 <a class="header-anchor" href="#_2-基础概念与产品层级" aria-label="Permalink to “2. 基础概念与产品层级”">​</a></h2><h3 id="_2-1-常见术语" tabindex="-1">2.1 常见术语 <a class="header-anchor" href="#_2-1-常见术语" aria-label="Permalink to “2.1 常见术语”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>术语</th><th>含义</th><th>说明</th></tr></thead><tbody><tr><td>NPU</td><td>Neural Processing Unit，神经网络处理器</td><td>昇腾产品文档中常用来指 AI 处理器设备；在不同产品语境中，需确认统计对象是芯片、模组还是卡。</td></tr><tr><td>Die</td><td>裸片</td><td>封装内部的独立硅片。多 Die 封装可将计算、I/O 等功能拆分到不同 Die。</td></tr><tr><td>AI Core</td><td>AI 计算核心</td><td>昇腾达芬奇架构中的计算资源单元，通常由矩阵计算、向量计算及数据搬运/控制机制协同完成任务。</td></tr><tr><td>Cube</td><td>矩阵计算单元</td><td>主要承担矩阵乘加、卷积等张量密集型计算。</td></tr><tr><td>Vector</td><td>向量计算单元</td><td>主要承担逐元素计算、激活、归一化、数据变换等操作。</td></tr><tr><td>HBM / 封装内高带宽内存</td><td>高带宽存储介质</td><td>与片上 SRAM/Cache 不同，通常以堆叠方式与计算芯片封装在一起，提供更大的容量和带宽。</td></tr><tr><td>HCCS</td><td>Huawei Cache Coherence System</td><td>华为 CPU/NPU 高速互联体系相关技术名称。</td></tr><tr><td>UB</td><td>Unified Bus，统一总线</td><td>昇腾超节点使用的高速互联协议/体系。950 系列采用 UB 2.0。</td></tr><tr><td>RoCE</td><td>RDMA over Converged Ethernet</td><td>基于以太网的 RDMA 通信方式，常用于跨节点或集群 Scale-Out 通信。</td></tr><tr><td>SuperPoD</td><td>超节点</td><td>将多个计算节点通过高速互联组合成统一资源域，使其在逻辑上更接近一台大型计算机。</td></tr></tbody></table></div><h3 id="_2-2-从芯片到集群的产品层级" tabindex="-1">2.2 从芯片到集群的产品层级 <a class="header-anchor" href="#_2-2-从芯片到集群的产品层级" aria-label="Permalink to “2.2 从芯片到集群的产品层级”">​</a></h3>`,13),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-184`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20%20%20A%5BAscend%20AI%20%E5%A4%84%E7%90%86%E5%99%A8%20%2F%20NPU%5D%20--%3E%20B%5B%E5%8A%A0%E9%80%9F%E5%8D%A1%E6%88%96%E8%AE%A1%E7%AE%97%E6%A8%A1%E7%BB%84%5D%0A%20%20%20%20B%20--%3E%20C%5BAI%20%E6%9C%8D%E5%8A%A1%E5%99%A8%20%2F%20%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%5D%0A%20%20%20%20C%20--%3E%20D%5B%E8%B6%85%E8%8A%82%E7%82%B9%20SuperPoD%5D%0A%20%20%20%20D%20--%3E%20E%5B%E6%99%BA%E7%AE%97%E9%9B%86%E7%BE%A4%20%2F%20%E6%95%B0%E6%8D%AE%E4%B8%AD%E5%BF%83%5D%0A%20%20%20%20F%5B%E9%B2%B2%E9%B9%8F%20CPU%E3%80%81DDR%E3%80%81%E5%AD%98%E5%82%A8%E3%80%81%E7%BD%91%E5%8D%A1%5D%20--%3E%20C%0A%20%20%20%20G%5B%E9%AB%98%E9%80%9F%E4%BA%92%E8%81%94%EF%BC%9AHCCS%20%2F%20UB%20%2F%20RoCE%5D%20--%3E%20D%0A%20%20%20%20H%5BCANN%E3%80%81HCCL%E3%80%81%E6%A1%86%E6%9E%B6%E4%B8%8E%E7%AE%97%E5%AD%90%E5%BA%93%5D%20--%3E%20A%0A`})]),fallback:t(()=>[...u[0]||=[o(` Loading... `,-1)]]),_:1})),u[9]||=s(`<p>理解昇腾硬件时，应区分以下几个层次：</p><ol><li><strong>芯片层：</strong> 关注计算核心数量、数据格式、内存容量与带宽、芯片内互联和 I/O 能力。</li><li><strong>卡/模组层：</strong> 关注芯片封装形态、供电、散热、板级接口、主机连接方式及实际可用算力。</li><li><strong>服务器层：</strong> 关注 NPU 数量、CPU/内存配置、PCIe 拓扑、卡间互联、网络和散热设计。</li><li><strong>超节点/集群层：</strong> 关注跨服务器互联拓扑、统一内存编址、集合通信效率、网络收敛比、故障域和运维能力。</li></ol><h2 id="_3-ascend-910c-硬件架构" tabindex="-1">3. Ascend 910C 硬件架构 <a class="header-anchor" href="#_3-ascend-910c-硬件架构" aria-label="Permalink to “3. Ascend 910C 硬件架构”">​</a></h2><h3 id="_3-1-产品定位" tabindex="-1">3.1 产品定位 <a class="header-anchor" href="#_3-1-产品定位" aria-label="Permalink to “3.1 产品定位”">​</a></h3><p>Ascend 910C 是面向数据中心 AI 训练和推理的高性能 NPU。华为在 2025 年公开介绍了 910C 与 Atlas 900 超节点的规模部署；2026 年 9 月的华为官方大会信息进一步披露，昇腾 910C 超节点累计部署已超过 1,000 套。[3][6]</p><p>从公开技术论文看，910C 采用双计算 Die 合封方案：两个计算 Die 集成在同一封装中，共享封装内存储资源，并通过高带宽 Die-to-Die 互联协同工作。需要注意，公开论文中的部分芯片内部参数属于论文披露口径，不应替代具体采购型号的数据手册。[7]</p><h3 id="_3-2-双-die-封装结构" tabindex="-1">3.2 双 Die 封装结构 <a class="header-anchor" href="#_3-2-双-die-封装结构" aria-label="Permalink to “3.2 双 Die 封装结构”">​</a></h3><p>公开论文描述的 910C 封装包含：</p><ul><li><strong>2 个计算 Die：</strong> 每个 Die 包含 24 个 AI Cube（AIC）和 48 个 AI Vector（AIV）；两个 Die 合计 48 个 AIC、96 个 AIV。</li><li><strong>封装内存储：</strong> 8 组内存堆栈，每组 16 GB，合计 128 GB；封装聚合内存带宽最高约 3.2 TB/s，单 Die 对应约 1.6 TB/s。</li><li><strong>Die 间互联：</strong> 论文给出的 Die 间互联带宽为双向合计约 540 GB/s（单向约 270 GB/s）。该数值是封装内部 Die-to-Die 通信口径，不应与服务器/超节点层面的外部互联带宽混为一谈。[7]</li></ul>`,9),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-245`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20%20%20subgraph%20PKG%5BAscend%20910C%20%E5%A4%9A%20Die%20%E5%B0%81%E8%A3%85%EF%BC%88%E6%A6%82%E5%BF%B5%E7%A4%BA%E6%84%8F%EF%BC%89%5D%0A%20%20%20%20%20%20subgraph%20D0%5B%E8%AE%A1%E7%AE%97%20Die%200%5D%0A%20%20%20%20%20%20%20%20C0%5B24%20%C3%97%20AI%20Cube%5D%0A%20%20%20%20%20%20%20%20V0%5B48%20%C3%97%20AI%20Vector%5D%0A%20%20%20%20%20%20end%0A%20%20%20%20%20%20subgraph%20D1%5B%E8%AE%A1%E7%AE%97%20Die%201%5D%0A%20%20%20%20%20%20%20%20C1%5B24%20%C3%97%20AI%20Cube%5D%0A%20%20%20%20%20%20%20%20V1%5B48%20%C3%97%20AI%20Vector%5D%0A%20%20%20%20%20%20end%0A%20%20%20%20%20%20LINK%5BDie-to-Die%20%E9%AB%98%E9%80%9F%E4%BA%92%E8%81%94%5D%0A%20%20%20%20%20%20MEM%5B%E5%B0%81%E8%A3%85%E5%86%85%E9%AB%98%E5%B8%A6%E5%AE%BD%E5%86%85%E5%AD%98%3Cbr%2F%3E8%20%E7%BB%84%20%C3%97%2016%20GB%20%3D%20128%20GB%3Cbr%2F%3E%E8%81%9A%E5%90%88%E5%B8%A6%E5%AE%BD%E7%BA%A6%203.2%20TB%2Fs%5D%0A%20%20%20%20%20%20D0%20---%20LINK%0A%20%20%20%20%20%20LINK%20---%20D1%0A%20%20%20%20%20%20D0%20---%20MEM%0A%20%20%20%20%20%20D1%20---%20MEM%0A%20%20%20%20end%0A`})]),fallback:t(()=>[...u[1]||=[o(` Loading... `,-1)]]),_:1})),u[10]||=s(`<p><strong>架构理解：</strong> Cube 负责高吞吐矩阵计算，Vector 负责矩阵主路径以外的向量和逐元素运算。大模型中的矩阵乘、注意力投影等算子通常更依赖 Cube；归一化、激活、量化/反量化、索引和数据重排等操作则会使用 Vector 以及数据搬运通路。实际执行效率取决于算子实现、数据布局、内存访问和计算/搬运流水线是否匹配。</p><h3 id="_3-3-计算精度与算力口径" tabindex="-1">3.3 计算精度与算力口径 <a class="header-anchor" href="#_3-3-计算精度与算力口径" aria-label="Permalink to “3.3 计算精度与算力口径”">​</a></h3><p>公开资料通常将 910C 的主要数据格式描述为 FP32、HF32、FP16、BF16 和 INT8。针对大模型训练，FP16/BF16 是常见的计算精度；推理场景可结合模型精度要求使用 INT8 量化。公开论文指出，910C 可通过 INT8 量化等方式提升低精度计算效率，但不能因此将其等同于原生硬件 FP8 支持。[3][7]</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>项目</th><th style="text-align:right;">公开资料中的典型口径</th><th>说明</th></tr></thead><tbody><tr><td>FP16 峰值算力</td><td style="text-align:right;">约 800 TFLOPS/芯片（按 Atlas 900 A3 的 384 卡、307.2 PFLOPS 峰值折算）</td><td>属于峰值理论口径；不同系统配置可能公布不同值。</td></tr><tr><td>封装内存容量</td><td style="text-align:right;">128 GB</td><td>以 Atlas 900 A3 产品页及公开论文口径为准。</td></tr><tr><td>封装内存带宽</td><td style="text-align:right;">最高约 3.2 TB/s</td><td>需区分芯片内存带宽与服务器 DDR 带宽。</td></tr><tr><td>数据格式</td><td style="text-align:right;">FP32、HF32、FP16、BF16、INT8</td><td>具体算子和软件版本支持情况以配套文档为准。</td></tr><tr><td>芯片内部 Die 互联</td><td style="text-align:right;">约 540 GB/s 双向合计</td><td>论文口径，属于封装内部链路。</td></tr></tbody></table></div><blockquote><p><strong>算力口径说明：</strong> Atlas 900 A3 官方产品页面公布的 384 NPU 系统 FP16 算力为 307.2/288.7 PFLOPS。307.2 PFLOPS 除以 384，折算为每个 NPU 约 800 TFLOPS。该折算便于理解系统规格，不代表所有硬件版本、散热/功耗限制和软件负载都能持续达到峰值。[2]</p></blockquote><h3 id="_3-4-内存子系统" tabindex="-1">3.4 内存子系统 <a class="header-anchor" href="#_3-4-内存子系统" aria-label="Permalink to “3.4 内存子系统”">​</a></h3><p>910C 的主要特点之一是较大的封装内高带宽内存容量和带宽。大模型训练和推理不只受峰值算力影响，也会受到权重、激活值、KV Cache、通信缓冲区及中间张量访问的影响。</p><ul><li><strong>容量决定可驻留数据规模：</strong> 模型权重、部分 KV Cache 或中间张量能否留在本地内存，会影响是否需要跨卡切分或访问其他存储层级。</li><li><strong>带宽决定数据供给速度：</strong> 对 Decode 等访存敏感型负载，内存带宽往往比矩阵峰值算力更能影响 Token 生成速度。</li><li><strong>局部性决定有效带宽：</strong> 连续访问、数据复用、算子融合和合理的分块策略有助于提高 HBM 利用率。</li></ul><p>不要将“128 GB 封装内存”与服务器的 DDR5 系统内存混为一谈。两者容量、带宽、访问路径及用途不同。</p><h3 id="_3-5-互联与通信" tabindex="-1">3.5 互联与通信 <a class="header-anchor" href="#_3-5-互联与通信" aria-label="Permalink to “3.5 互联与通信”">​</a></h3><p>大规模 AI 计算需要同时解决两类通信问题：</p><ul><li><strong>Scale-Up（节点内/超节点内扩展）：</strong> 让同一超节点中的多颗 NPU 以高带宽、低时延方式互联，支撑张量并行、专家并行和跨卡数据交换。</li><li><strong>Scale-Out（超节点间/集群间扩展）：</strong> 通过网络连接多个计算节点或超节点，支撑更大规模任务和资源池化。</li></ul><p>Atlas 900 A3 官方规格给出的关键指标包括：最大支持 384 NPU 高速互联、D2D 双向带宽 784 GB/s、48 TB 片上内存统一编址、总线带宽 1:1 无收敛以及约 200 ns 通信单跳时延。[2]</p><p>公开的 CloudMatrix384 技术论文进一步描述了一个计算节点的组成：8 个 910C NPU、4 个鲲鹏 CPU 和 7 个 UB 交换芯片；整个超节点由 48 个计算节点组成，合计 384 个 NPU，使用 12 个计算机柜和 4 个通信机柜。论文区分了 UB、RDMA 和 VPC 三类网络平面：UB 用于超节点内高速 Scale-Up，RDMA 用于 Scale-Out，VPC 用于管理、存储访问和外部业务流量。[7]</p>`,14),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-382`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20%20%20subgraph%20SN%5BCloudMatrix384%20%2F%20384%20NPU%20%E8%B6%85%E8%8A%82%E7%82%B9%EF%BC%88%E8%AE%BA%E6%96%87%E6%8B%93%E6%89%91%E6%8A%BD%E8%B1%A1%EF%BC%89%5D%0A%20%20%20%20%20%20subgraph%20NODE1%5B%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%201%5D%0A%20%20%20%20%20%20%20%20CPU1%5B4%20%C3%97%20%E9%B2%B2%E9%B9%8F%20CPU%5D%0A%20%20%20%20%20%20%20%20NPU1%5B8%20%C3%97%20Ascend%20910C%20NPU%5D%0A%20%20%20%20%20%20%20%20SW1%5B%E6%9D%BF%E8%BD%BD%20UB%20%E4%BA%A4%E6%8D%A2%E8%B5%84%E6%BA%90%5D%0A%20%20%20%20%20%20%20%20CPU1%20---%20SW1%0A%20%20%20%20%20%20%20%20NPU1%20---%20SW1%0A%20%20%20%20%20%20end%0A%20%20%20%20%20%20subgraph%20NODE2%5B%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%202%5D%0A%20%20%20%20%20%20%20%20CPU2%5B4%20%C3%97%20%E9%B2%B2%E9%B9%8F%20CPU%5D%0A%20%20%20%20%20%20%20%20NPU2%5B8%20%C3%97%20Ascend%20910C%20NPU%5D%0A%20%20%20%20%20%20%20%20SW2%5B%E6%9D%BF%E8%BD%BD%20UB%20%E4%BA%A4%E6%8D%A2%E8%B5%84%E6%BA%90%5D%0A%20%20%20%20%20%20%20%20CPU2%20---%20SW2%0A%20%20%20%20%20%20%20%20NPU2%20---%20SW2%0A%20%20%20%20%20%20end%0A%20%20%20%20%20%20FAB%5B%E6%9C%BA%E6%9F%9C%E7%BA%A7%20UB%20%E4%BA%A4%E6%8D%A2%E7%BD%91%E7%BB%9C%5D%0A%20%20%20%20%20%20NODE1%20---%20FAB%0A%20%20%20%20%20%20NODE2%20---%20FAB%0A%20%20%20%20%20%20MORE%5B%E5%85%B6%E4%BD%99%E8%AE%A1%E7%AE%97%E8%8A%82%E7%82%B9%E2%80%A6%E2%80%A6%E5%85%B1%2048%20%E4%B8%AA%E8%8A%82%E7%82%B9%5D%0A%20%20%20%20%20%20MORE%20---%20FAB%0A%20%20%20%20end%0A%20%20%20%20FAB%20--%3E%20RDMA%5BRDMA%20%2F%20RoCE%EF%BC%9AScale-Out%5D%0A%20%20%20%20FAB%20--%3E%20VPC%5BVPC%EF%BC%9A%E7%AE%A1%E7%90%86%E3%80%81%E5%AD%98%E5%82%A8%E5%8F%8A%E5%A4%96%E9%83%A8%E4%B8%9A%E5%8A%A1%E7%BD%91%E7%BB%9C%5D%0A`})]),fallback:t(()=>[...u[2]||=[o(` Loading... `,-1)]]),_:1})),u[11]||=s(`<blockquote><p><strong>注意：</strong> 上图是根据论文描述的逻辑拓扑绘制的抽象图，不是板卡级布线图。论文中的单向链路速率、系统产品页的双向 D2D 速率及不同互联层级的带宽定义不同，引用数据时必须带上测量层级和单向/双向口径。[2][7]</p></blockquote><h3 id="_3-6-代表性产品形态-atlas-900-a3-superpod" tabindex="-1">3.6 代表性产品形态：Atlas 900 A3 SuperPoD <a class="header-anchor" href="#_3-6-代表性产品形态-atlas-900-a3-superpod" aria-label="Permalink to “3.6 代表性产品形态：Atlas 900 A3 SuperPoD”">​</a></h3><p>Atlas 900 A3 SuperPoD 是 910C 代际的重要系统形态。其官方资料列出的主要规格如下：[2]</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>项目</th><th>Atlas 900 A3 SuperPoD 公开规格</th></tr></thead><tbody><tr><td>产品定位</td><td>高性能、高能效液冷训练超节点</td></tr><tr><td>机柜形态</td><td>12 个计算柜（47U）+ 4 个总线设备柜（47U）</td></tr><tr><td>NPU</td><td>最大 384 × 昇腾 910 系列 NPU</td></tr><tr><td>CPU</td><td>最大 192 × 鲲鹏 920</td></tr><tr><td>系统内存</td><td>最大 1,536 根 DDR5，最高 5,200 MT/s；单根支持 64 GB/96 GB</td></tr><tr><td>片上内存</td><td>最大 384 × 128 GB，最大带宽 3.2 TB/s</td></tr><tr><td>FP16 算力</td><td>307.2/288.7 PFLOPS</td></tr><tr><td>D2D 互联</td><td>双向 784 GB/s</td></tr><tr><td>本地存储</td><td>最大 480 块 2.5 英寸硬盘</td></tr><tr><td>散热</td><td>计算柜液冷、总线设备柜风冷</td></tr><tr><td>工作温度</td><td>5℃～40℃</td></tr></tbody></table></div><p>该系统的重点不是简单地把大量服务器放在同一机房，而是通过高速总线、统一内存编址和系统级调度，将多个计算节点组织成统一资源域。其优势主要体现在大规模模型训练、MoE 专家并行、跨卡 KV Cache 访问及高并发推理等通信密集型场景。</p><h2 id="_4-ascend-910c-软件栈与开发方式" tabindex="-1">4. Ascend 910C 软件栈与开发方式 <a class="header-anchor" href="#_4-ascend-910c-软件栈与开发方式" aria-label="Permalink to “4. Ascend 910C 软件栈与开发方式”">​</a></h2><p>昇腾硬件需要与驱动、固件、CANN、框架适配层、算子库和通信库配套使用。软件版本、驱动固件和硬件型号之间存在严格的兼容关系，不能只安装一个框架包就认为环境已经就绪。</p><h3 id="_4-1-软件栈分层" tabindex="-1">4.1 软件栈分层 <a class="header-anchor" href="#_4-1-软件栈分层" aria-label="Permalink to “4.1 软件栈分层”">​</a></h3>`,8),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-508`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20%20%20APP%5BAI%20%E5%BA%94%E7%94%A8%20%2F%20%E5%A4%A7%E6%A8%A1%E5%9E%8B%E8%AE%AD%E7%BB%83%E4%B8%8E%E6%8E%A8%E7%90%86%5D%0A%20%20%20%20FW%5BAI%20%E6%A1%86%E6%9E%B6%EF%BC%9APyTorch%20%2F%20MindSpore%20%2F%20TensorFlow%5D%0A%20%20%20%20ADAPT%5B%E6%A1%86%E6%9E%B6%E9%80%82%E9%85%8D%EF%BC%9Atorch_npu%20%E7%AD%89%5D%0A%20%20%20%20CANN%5BCANN%EF%BC%9A%E7%BC%96%E8%AF%91%E5%99%A8%E3%80%81Runtime%E3%80%81%E7%AE%97%E5%AD%90%E5%BA%93%E3%80%81%E5%9B%BE%E4%B8%8E%E6%89%A7%E8%A1%8C%E7%AE%A1%E7%90%86%5D%0A%20%20%20%20COMM%5BHCCL%EF%BC%9A%E5%8D%95%E6%9C%BA%E5%A4%9A%E5%8D%A1%20%2F%20%E5%A4%9A%E6%9C%BA%E5%A4%9A%E5%8D%A1%E9%9B%86%E5%90%88%E9%80%9A%E4%BF%A1%5D%0A%20%20%20%20DRIVER%5B%E9%A9%B1%E5%8A%A8%E4%B8%8E%E5%9B%BA%E4%BB%B6%5D%0A%20%20%20%20HW%5BAscend%20NPU%EF%BC%9A910C%20%2F%20950%5D%0A%20%20%20%20APP%20--%3E%20FW%20--%3E%20ADAPT%20--%3E%20CANN%20--%3E%20DRIVER%20--%3E%20HW%0A%20%20%20%20FW%20--%3E%20COMM%0A%20%20%20%20COMM%20--%3E%20CANN%0A`})]),fallback:t(()=>[...u[3]||=[o(` Loading... `,-1)]]),_:1})),u[12]||=s(`<p>主要组件如下：</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>组件</th><th>主要职责</th></tr></thead><tbody><tr><td>CANN</td><td>昇腾异构计算架构，承接上层框架与底层 AI 处理器，提供编译、运行时、算子库和多层次编程接口。</td></tr><tr><td>torch_npu</td><td>PyTorch 与昇腾 NPU 之间的适配扩展，使 PyTorch 程序能够调用 NPU。</td></tr><tr><td>MindSpore</td><td>华为开源 AI 框架之一，可用于模型开发、训练和推理。</td></tr><tr><td>HCCL</td><td>昇腾集合通信库，提供 AllReduce、AllGather、ReduceScatter、AlltoAll、Broadcast 等通信原语。</td></tr><tr><td>Ascend C</td><td>面向昇腾 AI 处理器的算子编程语言及开发接口，用于开发、调试和优化自定义算子。</td></tr><tr><td>MindSpeed 等加速套件</td><td>面向大模型训练的并行策略、算子和性能优化组件，实际使用需核对版本配套。</td></tr></tbody></table></div><p>HCCL 可基于 HCCS、RoCE 和 PCIe 等链路实现集合通信，常见操作包括 AllReduce、AllGather、ReduceScatter 和 AlltoAll。其核心流程包括通信域初始化、建立通信连接、执行通信操作和销毁通信域。[8]</p><h3 id="_4-2-模型运行流程" tabindex="-1">4.2 模型运行流程 <a class="header-anchor" href="#_4-2-模型运行流程" aria-label="Permalink to “4.2 模型运行流程”">​</a></h3>`,4),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-580`,class:`mermaid`,graph:`flowchart%20TD%0A%20%20%20%20A%5B%E6%A8%A1%E5%9E%8B%E4%BB%A3%E7%A0%81%E4%B8%8E%E6%A8%A1%E5%9E%8B%E6%9D%83%E9%87%8D%5D%20--%3E%20B%5B%E6%A1%86%E6%9E%B6%E6%9E%84%E5%9B%BE%20%2F%20eager%20%E6%89%A7%E8%A1%8C%5D%0A%20%20%20%20B%20--%3E%20C%5B%E6%A1%86%E6%9E%B6%E9%80%82%E9%85%8D%E4%B8%8E%E7%AE%97%E5%AD%90%E6%98%A0%E5%B0%84%5D%0A%20%20%20%20C%20--%3E%20D%5BCANN%20%E7%BC%96%E8%AF%91%E3%80%81%E5%9B%BE%E4%BC%98%E5%8C%96%E4%B8%8E%E7%AE%97%E5%AD%90%E9%80%89%E6%8B%A9%5D%0A%20%20%20%20D%20--%3E%20E%5BRuntime%20%E4%B8%8B%E5%8F%91%E6%89%A7%E8%A1%8C%E4%BB%BB%E5%8A%A1%5D%0A%20%20%20%20E%20--%3E%20F%5B%E9%A9%B1%E5%8A%A8%20%2F%20%E5%9B%BA%E4%BB%B6%E8%B0%83%E5%BA%A6%20NPU%5D%0A%20%20%20%20F%20--%3E%20G%5BCube%20%2F%20Vector%20%E5%B9%B6%E8%A1%8C%E8%AE%A1%E7%AE%97%5D%0A%20%20%20%20G%20--%3E%20H%5BHBM%20%E4%B8%8E%E7%89%87%E4%B8%8A%E7%BC%93%E5%AD%98%E8%AF%BB%E5%86%99%5D%0A%20%20%20%20H%20--%3E%20I%5B%E7%BB%93%E6%9E%9C%E5%9B%9E%E4%BC%A0%20%2F%20HCCL%20%E9%9B%86%E5%90%88%E9%80%9A%E4%BF%A1%5D%0A%20%20%20%20I%20--%3E%20J%5B%E6%A1%86%E6%9E%B6%E6%B1%87%E6%80%BB%E7%BB%93%E6%9E%9C%E5%B9%B6%E7%BB%A7%E7%BB%AD%E8%BF%AD%E4%BB%A3%5D%0A`})]),fallback:t(()=>[...u[4]||=[o(` Loading... `,-1)]]),_:1})),u[13]||=s(`<h3 id="_4-3-部署与版本管理建议" tabindex="-1">4.3 部署与版本管理建议 <a class="header-anchor" href="#_4-3-部署与版本管理建议" aria-label="Permalink to “4.3 部署与版本管理建议”">​</a></h3><ol><li><strong>先确定硬件型号和操作系统。</strong> 明确是 910C 对应的具体 Atlas 服务器/超节点型号，确认 CPU 架构、操作系统和驱动支持范围。</li><li><strong>按官方版本配套表安装。</strong> 驱动、固件、CANN、PyTorch、torch_npu、HCCL 和第三方模型服务框架需按兼容矩阵匹配。</li><li><strong>优先验证基础算子和通信。</strong> 在跑完整模型前，先验证设备可见性、基础矩阵算子、内存分配、单机多卡集合通信和跨节点通信。</li><li><strong>对目标模型做端到端基准测试。</strong> 不能只用 GEMM 峰值推算模型吞吐；应使用真实序列长度、批量大小、并行策略、精度和 KV Cache 配置进行验证。</li><li><strong>生产环境优先采用稳定版本。</strong> 例如 CANN 文档页截至 2026 年 11 月列出了 9.3.0-beta.1，并新增面向 950PR/950DT 的能力；Beta 版本适合验证新特性，不应未经测试直接作为生产默认版本。[9]</li></ol><h2 id="_5-ascend-950-系列介绍" tabindex="-1">5. Ascend 950 系列介绍 <a class="header-anchor" href="#_5-ascend-950-系列介绍" aria-label="Permalink to “5. Ascend 950 系列介绍”">​</a></h2><h3 id="_5-1-代际定位与主要变化" tabindex="-1">5.1 代际定位与主要变化 <a class="header-anchor" href="#_5-1-代际定位与主要变化" aria-label="Permalink to “5.1 代际定位与主要变化”">​</a></h3><p>950 系列是昇腾后续一代高性能 AI 处理器。华为在 2025 年公开的路线图中介绍，950PR 与 950DT 共用 Ascend 950 Die，但通过不同的高带宽存储方案和产品配置，分别面向不同的计算负载。[3]</p><p>与 910C 相比，950 系列重点升级如下：</p><ul><li><strong>数值格式：</strong> 增加对 FP8、MXFP8、MXFP4、HiF8 等格式的支持，提升低精度训练和推理吞吐。</li><li><strong>编程模型：</strong> 支持 SIMD/SIMT 双编程模型。SIMD 适合大块、规整的数据并行处理；SIMT 适合更灵活、细粒度或不规则的并行任务。</li><li><strong>向量能力：</strong> 提高向量计算资源占比，强化张量计算与向量计算的协同能力。</li><li><strong>访存颗粒度：</strong> 将内存访问颗粒度由 512 Byte 优化至 128 Byte，改善小算子和离散、不连续访存场景。[3]</li><li><strong>互联：</strong> 引入灵衢 UB 2.0，支持 URMA 异步远程访存和 UB Memory 全局 Load/Store 内存语义，并支持 PCIe 5.0 x16 与 2 × 400 Gbps UBoE 接口。[4]</li></ul><h3 id="_5-2-950pr-与-950dt-的差异" tabindex="-1">5.2 950PR 与 950DT 的差异 <a class="header-anchor" href="#_5-2-950pr-与-950dt-的差异" aria-label="Permalink to “5.2 950PR 与 950DT 的差异”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>对比维度</th><th>Ascend 950PR</th><th>Ascend 950DT</th></tr></thead><tbody><tr><td>主要定位</td><td>推理 Prefill、推荐业务</td><td>推理 Decode、大模型训练</td></tr><tr><td>典型负载特征</td><td>计算密集，对访存带宽的相对要求较低</td><td>访存和互联压力较高，需要更强内存带宽与容量</td></tr><tr><td>存储方案</td><td>HiBL 1.0，偏成本优化</td><td>HiZQ 2.0，偏高性能访存</td></tr><tr><td>产品形态</td><td>Atlas 350 等加速卡</td><td>Atlas 950 SuperPoD / A5 超节点方案</td></tr><tr><td>典型使用场景</td><td>长上下文 Prefill、推荐排序、多模态生成中的计算密集阶段</td><td>Decode、训练、MoE 通信和高并发推理</td></tr></tbody></table></div><p><strong>Prefill 与 Decode 的差别：</strong> Prefill 阶段需要并行处理输入提示词，通常具有较高的矩阵计算密度；Decode 阶段逐 Token 生成，对权重与 KV Cache 的反复访问更加敏感。因此，采用面向 Prefill 优化的 950PR 与面向 Decode/训练优化的 950DT，是针对工作负载差异进行的产品分化，而不是简单的性能档位区分。[3]</p><h3 id="_5-3-950dt-多-die-架构" tabindex="-1">5.3 950DT 多 Die 架构 <a class="header-anchor" href="#_5-3-950dt-多-die-架构" aria-label="Permalink to “5.3 950DT 多 Die 架构”">​</a></h3><p>华为云 2026 年 10 月更新的 Atlas 950 产品文档披露，950DT 是多 Die 合封芯片，包含 <strong>2 个 AI Die、2 个 I/O Die 和 4 个高速片上内存模块</strong>。各 Die 与内存模块通过高速 D2D Clink 和 Memory Interface 互联，构成统一内存访问（UMA）整体。[4]</p><p>文档披露的主要组件如下：</p><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>组件</th><th>公开规格</th></tr></thead><tbody><tr><td>AI 子系统</td><td>36 个第三代 DaVinci AI 子系统；每个包括 1 个 Cube Core 和 2 个 Vector Core</td></tr><tr><td>AI CPU</td><td>4 个 AI CPU Cluster；每个 Cluster 包括 2 个 Linx816 双线程处理器及 4 MB L3 Cache</td></tr><tr><td>图像/视频处理</td><td>4 个 DVPP 子系统，包括 VPC、JPEGE 和 JPEGD Core</td></tr><tr><td>L2 Cache</td><td>128 MB，统一访问</td></tr><tr><td>任务调度</td><td>STARS 2.0</td></tr><tr><td>高速片上内存</td><td>最高 96 GB，带宽最高 4 TB/s（950DT 当前产品文档口径）</td></tr><tr><td>主机接口</td><td>PCIe Gen5 x16，向下兼容 Gen4/3/2/1</td></tr><tr><td>互联</td><td>UB 2.0；支持 URMA、UB Memory；2 × 400 Gbps UBoE</td></tr></tbody></table></div>`,14),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-815`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20%20%20subgraph%20CHIP%5BAscend%20950DT%20%E5%A4%9A%20Die%20%E5%B0%81%E8%A3%85%EF%BC%88%E5%9F%BA%E4%BA%8E%E5%8D%8E%E4%B8%BA%E4%BA%91%E4%BA%A7%E5%93%81%E6%96%87%E6%A1%A3%EF%BC%89%5D%0A%20%20%20%20%20%20AI1%5BAI%20Die%200%5D%0A%20%20%20%20%20%20AI2%5BAI%20Die%201%5D%0A%20%20%20%20%20%20IO1%5BI%2FO%20Die%200%5D%0A%20%20%20%20%20%20IO2%5BI%2FO%20Die%201%5D%0A%20%20%20%20%20%20MEM%5B4%20%E4%B8%AA%E9%AB%98%E9%80%9F%E7%89%87%E4%B8%8A%E5%86%85%E5%AD%98%E6%A8%A1%E5%9D%97%3Cbr%2F%3E%E6%9C%80%E9%AB%98%2096%20GB%20%2F%204%20TB%2Fs%5D%0A%20%20%20%20%20%20CTRL%5BSTARS%202.0%20%2F%20128%20MB%20L2%20%2F%20AI%20CPU%20%E5%AD%90%E7%B3%BB%E7%BB%9F%5D%0A%20%20%20%20%20%20AI1%20%3C--%3E%20MEM%0A%20%20%20%20%20%20AI2%20%3C--%3E%20MEM%0A%20%20%20%20%20%20AI1%20%3C--%3E%20IO1%0A%20%20%20%20%20%20AI2%20%3C--%3E%20IO2%0A%20%20%20%20%20%20IO1%20%3C--%3E%20IO2%0A%20%20%20%20%20%20CTRL%20---%20AI1%0A%20%20%20%20%20%20CTRL%20---%20AI2%0A%20%20%20%20end%0A%20%20%20%20CHIP%20--%3E%20PCIe%5BPCIe%205.0%20x16%5D%0A%20%20%20%20CHIP%20--%3E%20UB%5BUB%202.0%20%2F%20URMA%20%2F%20UB%20Memory%5D%0A%20%20%20%20CHIP%20--%3E%20E%5B2%20%C3%97%20400%20Gbps%20UBoE%5D%0A`})]),fallback:t(()=>[...u[5]||=[o(` Loading... `,-1)]]),_:1})),u[14]||=s(`<blockquote><p>图为功能关系示意，不代表实际 Die 摆放、物理布线或信号拓扑。芯片内存模块、Cache 和系统内存是不同存储层级，不应混为一谈。[4]</p></blockquote><h3 id="_5-4-950pr-偏-prefill-与推荐" tabindex="-1">5.4 950PR：偏 Prefill 与推荐 <a class="header-anchor" href="#_5-4-950pr-偏-prefill-与推荐" aria-label="Permalink to “5.4 950PR：偏 Prefill 与推荐”">​</a></h3><p>950PR 的产品定位是推理 Prefill 和推荐业务。华为 2025 年路线图介绍，950PR 采用 HiBL 1.0，目标是以较低的存储成本满足计算密集型推理阶段和推荐场景的需求。Atlas 350 是搭载 950PR 的加速卡产品，官方发布信息强调其向量算力提升和更细粒度 Cacheline 访问能力。[3][10]</p><p>在选型时，950PR 应重点关注：</p><ul><li>长上下文 Prefill 的吞吐和首 Token 时延（TTFT）；</li><li>推荐模型的样本吞吐、特征访问效率及在线时延；</li><li>小算子、向量算子和不规则访存的优化程度；</li><li>实际卡级内存容量、带宽、功耗与服务器兼容性。</li></ul><h3 id="_5-5-950dt-偏-decode-与训练" tabindex="-1">5.5 950DT：偏 Decode 与训练 <a class="header-anchor" href="#_5-5-950dt-偏-decode-与训练" aria-label="Permalink to “5.5 950DT：偏 Decode 与训练”">​</a></h3><p>950DT 面向推理 Decode 和训练场景。较新的华为云产品文档列出了 950DT 单芯片最高 96 GB 高速片上内存和 4 TB/s 带宽，并明确了多 Die、UMA 和 UB 2.0 的产品实现方式。[4]</p><p>在选型时，950DT 应重点关注：</p><ul><li>Decode 阶段每秒生成 Token 数、TPOT（每 Token 输出时延）和长上下文下的吞吐变化；</li><li>大模型训练的 MFU、跨卡集合通信耗时和扩展效率；</li><li>MoE 训练/推理中的 All-to-All 通信效率；</li><li>超节点统一内存访问、跨模组通信以及故障隔离能力。</li></ul><h3 id="_5-6-950-超节点-atlas-950-superpod" tabindex="-1">5.6 950 超节点：Atlas 950 SuperPoD <a class="header-anchor" href="#_5-6-950-超节点-atlas-950-superpod" aria-label="Permalink to “5.6 950 超节点：Atlas 950 SuperPoD”">​</a></h3><p>2026 年 7 月，华为首次公开展示 Atlas 950 SuperPoD 的 1024 卡真机集群，公布的展示配置指标包括 1 EFLOPS FP8、2 EFLOPS FP4、256 TB 全局统一内存编址空间和约 3 μs RTT 时延。[11]</p><p>华为云 2026 年 10—11 月更新的 A5 产品文档进一步明确，当前公开的 Atlas 950 A5 超节点支持 64～1024 个 NPU 模组；1024 规模配置由 16 个计算柜和 2 个灵衢互联柜组成，每个计算柜包含 64 组 NPU 模组，并采用 8 个超平面进行互联。系统支持液冷和柜级预集成交付。[4][5]</p>`,12),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-892`,class:`mermaid`,graph:`flowchart%20TB%0A%20%20%20%20subgraph%20POD%5BAtlas%20950%20A5%20%2F%201024%20NPU%20%E6%A8%A1%E7%BB%84%E9%85%8D%E7%BD%AE%EF%BC%88%E9%80%BB%E8%BE%91%E7%A4%BA%E6%84%8F%EF%BC%89%5D%0A%20%20%20%20%20%20subgraph%20COMPUTE%5B%E8%AE%A1%E7%AE%97%E6%9F%9C%EF%BC%9A16%20%E6%9F%9C%5D%0A%20%20%20%20%20%20%20%20C1%5B%E8%AE%A1%E7%AE%97%E6%9F%9C%201%3Cbr%2F%3E64%20%E7%BB%84%20NPU%20%E6%A8%A1%E7%BB%84%5D%0A%20%20%20%20%20%20%20%20C2%5B%E8%AE%A1%E7%AE%97%E6%9F%9C%202%3Cbr%2F%3E64%20%E7%BB%84%20NPU%20%E6%A8%A1%E7%BB%84%5D%0A%20%20%20%20%20%20%20%20C3%5B%E2%80%A6%E2%80%A6%5D%0A%20%20%20%20%20%20%20%20C16%5B%E8%AE%A1%E7%AE%97%E6%9F%9C%2016%3Cbr%2F%3E64%20%E7%BB%84%20NPU%20%E6%A8%A1%E7%BB%84%5D%0A%20%20%20%20%20%20end%0A%20%20%20%20%20%20subgraph%20INTERCONNECT%5B%E7%81%B5%E8%A1%A2%E4%BA%92%E8%81%94%E6%9F%9C%EF%BC%9A2%20%E6%9F%9C%5D%0A%20%20%20%20%20%20%20%20L1%5BUB%20%E4%BA%92%E8%81%94%E8%AE%BE%E5%A4%87%20%2F%20%E4%BA%A4%E6%8D%A2%E8%B5%84%E6%BA%90%5D%0A%20%20%20%20%20%20%20%20L2%5BUB%20%E4%BA%92%E8%81%94%E8%AE%BE%E5%A4%87%20%2F%20%E4%BA%A4%E6%8D%A2%E8%B5%84%E6%BA%90%5D%0A%20%20%20%20%20%20end%0A%20%20%20%20%20%20C1%20%3C--%3E%20L1%0A%20%20%20%20%20%20C2%20%3C--%3E%20L1%0A%20%20%20%20%20%20C3%20%3C--%3E%20L1%0A%20%20%20%20%20%20C16%20%3C--%3E%20L2%0A%20%20%20%20%20%20L1%20%3C--%3E%20L2%0A%20%20%20%20end%0A`})]),fallback:t(()=>[...u[6]||=[o(` Loading... `,-1)]]),_:1})),u[15]||=s(`<blockquote><p>说明：这里的“1024”是华为云 A5 产品文档所描述的 NPU 模组总数口径；“计算柜”“互联柜”和“平面”属于系统级组网概念。不同交付形态可能采用不同规模和机柜组合。[5]</p></blockquote><h3 id="_5-7-950-产品进展与公开规格口径" tabindex="-1">5.7 950 产品进展与公开规格口径 <a class="header-anchor" href="#_5-7-950-产品进展与公开规格口径" aria-label="Permalink to “5.7 950 产品进展与公开规格口径”">​</a></h3><p>截至本文日期（2026-11-23）：</p><ul><li>950PR 已以 Atlas 350 加速卡形态公开发布；950PR 主要面向 Prefill、推荐等推理负载。[10]</li><li>950DT 已进入 Atlas 950/A5 超节点产品体系；华为云的产品文档已公开其芯片结构和系统组网方式。[4][5]</li><li>华为在 2026 年 9 月公开表示，昇腾 950 超节点已实现规模商用；华为云同时披露了 950 智算集群服务的商用安排。[6][12]</li></ul><p><strong>关于 950DT 内存容量的公开数据差异：</strong> 华为 2025 年路线图演讲曾提及 950DT 144 GB 的规划口径；华为云 2026 年 10 月更新的 Atlas 950/A5 产品文档则列出 950DT 单芯片最高 96 GB、4 TB/s。两者可能对应不同规划阶段、产品实现或容量定义。本文在介绍当前 A5/950DT 产品实现时采用较新的华为云产品文档口径；实际项目必须以具体 SKU、模组和交付配置的数据手册为准。[3][4]</p><p><strong>关于 950 超节点规模：</strong> 2025 年路线图演讲曾披露 Atlas 950 满配 8192 卡的规划形态；2026 年公开的 Atlas 950/A5 实施文档明确给出 64～1024 NPU 模组的当前组网配置。应区分早期整机路线图规划、当前 A5 超节点交付规格，以及超节点集群的多 Pod 扩展规模，不能将三种口径直接视为同一配置。[3][5]</p><h2 id="_6-910c-与-950-系列对比" tabindex="-1">6. 910C 与 950 系列对比 <a class="header-anchor" href="#_6-910c-与-950-系列对比" aria-label="Permalink to “6. 910C 与 950 系列对比”">​</a></h2><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>对比维度</th><th>Ascend 910C</th><th>Ascend 950 系列</th></tr></thead><tbody><tr><td>代际定位</td><td>面向大规模训练与推理的高性能 NPU</td><td>下一代产品，按 Prefill/推荐与 Decode/训练进行细分</td></tr><tr><td>计算架构</td><td>DaVinci；公开论文描述为双计算 Die</td><td>第三代 DaVinci；采用 SIMD/SIMT 双编程模型</td></tr><tr><td>计算单元</td><td>公开论文：每 Die 24 AIC + 48 AIV</td><td>950DT 产品文档：36 个 AI 子系统，每个 1 Cube + 2 Vector</td></tr><tr><td>主要精度</td><td>FP32、HF32、FP16、BF16、INT8</td><td>FP32、HF32、FP16、BF16、FP8、MXFP8、HiF8、MXFP4 等</td></tr><tr><td>封装内存</td><td>128 GB，约 3.2 TB/s</td><td>PR/DT 存储方案不同；950DT 当前 A5 产品文档为最高 96 GB、4 TB/s</td></tr><tr><td>互联代际</td><td>灵衢 1.0 / HCCS 体系</td><td>灵衢 2.0 / UB 2.0，支持 URMA 和 UB Memory</td></tr><tr><td>代表系统</td><td>Atlas 900 A3 / CloudMatrix384</td><td>Atlas 950 SuperPoD / A5</td></tr><tr><td>典型场景</td><td>大规模训练、推理、384 NPU 级超节点</td><td>PR：Prefill/推荐；DT：Decode/训练；1024 NPU 模组级超节点</td></tr></tbody></table></div><p><strong>核心差异总结：</strong> 910C 的系统能力已经通过 384 NPU 级超节点得到验证；950 的重点不只是单芯片算力增加，而是通过低精度格式、SIMD/SIMT、向量能力增强、内存子系统分化和 UB 2.0，提升不同推理阶段及训练任务的整体效率。</p><h2 id="_7-典型应用场景与选型建议" tabindex="-1">7. 典型应用场景与选型建议 <a class="header-anchor" href="#_7-典型应用场景与选型建议" aria-label="Permalink to “7. 典型应用场景与选型建议”">​</a></h2><h3 id="_7-1-场景映射" tabindex="-1">7.1 场景映射 <a class="header-anchor" href="#_7-1-场景映射" aria-label="Permalink to “7.1 场景映射”">​</a></h3><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>场景</th><th>推荐重点关注的硬件方向</th><th>关键评估指标</th></tr></thead><tbody><tr><td>大模型预训练</td><td>910C 大规模超节点；950DT 新一代训练系统</td><td>MFU、训练步时、集合通信占比、扩展效率、稳定性</td></tr><tr><td>大模型后训练/微调</td><td>910C 或 950DT，按模型规模与软件支持选择</td><td>训练吞吐、显存/内存容量、并行策略、Checkpoint 时间</td></tr><tr><td>在线推理 Prefill</td><td>950PR</td><td>TTFT、输入 Token/s、长上下文批处理效率</td></tr><tr><td>在线推理 Decode</td><td>950DT；也可评估现有 910C 部署</td><td>TPOT、输出 Token/s、KV Cache 容量与带宽</td></tr><tr><td>推荐系统</td><td>950PR</td><td>QPS、尾时延、特征访存效率、精度和成本</td></tr><tr><td>MoE 大规模推理</td><td>910C/950DT 超节点及高速互联</td><td>All-to-All 带宽、专家负载均衡、跨卡通信时延</td></tr></tbody></table></div><h3 id="_7-2-选型时需要核对的项目" tabindex="-1">7.2 选型时需要核对的项目 <a class="header-anchor" href="#_7-2-选型时需要核对的项目" aria-label="Permalink to “7.2 选型时需要核对的项目”">​</a></h3><ol><li><strong>模型及算子适配：</strong> 目标模型是否已有昇腾适配版本；关键算子是否有高性能实现；是否需要自定义算子。</li><li><strong>精度策略：</strong> FP16/BF16/INT8 或 FP8/MXFP8/HiF8/MXFP4 的精度损失和吞吐收益是否符合业务要求。</li><li><strong>内存容量：</strong> 权重、激活、KV Cache、通信缓冲和运行时开销是否能在目标卡数下满足要求。</li><li><strong>互联拓扑：</strong> 节点内、柜内、超节点内和跨集群分别采用什么链路；是否存在超售、收敛或拥塞风险。</li><li><strong>散热与供电：</strong> 风冷/液冷方式、机房供回水能力、单柜功率密度、供电冗余和 PUE 目标。</li><li><strong>软件兼容性：</strong> 驱动、固件、CANN、框架、HCCL、推理引擎和容器镜像的版本组合是否经过验证。</li><li><strong>实际业务基准：</strong> 使用真实模型、输入输出长度、并发量和 SLA 测试；重点统计吞吐、首 Token 时延、单 Token 时延、P95/P99 尾时延和故障恢复时间。</li></ol><h3 id="_7-3-性能评估方法" tabindex="-1">7.3 性能评估方法 <a class="header-anchor" href="#_7-3-性能评估方法" aria-label="Permalink to “7.3 性能评估方法”">​</a></h3><p>建议按“单卡—单机—超节点—集群”逐级验证：</p>`,16),(e(),l(i,null,{default:t(()=>[r(h,{id:`mermaid-1173`,class:`mermaid`,graph:`flowchart%20TD%0A%20%20%20%20A%5B%E5%8D%95%E5%8D%A1%E6%B5%8B%E8%AF%95%EF%BC%9A%E7%AE%97%E5%AD%90%E3%80%81HBM%E3%80%81%E5%8A%9F%E8%80%97%5D%20--%3E%20B%5B%E5%8D%95%E6%9C%BA%E5%A4%9A%E5%8D%A1%EF%BC%9A%E5%8D%A1%E9%97%B4%E9%80%9A%E4%BF%A1%E4%B8%8E%E5%B9%B6%E8%A1%8C%E6%95%88%E7%8E%87%5D%0A%20%20%20%20B%20--%3E%20C%5B%E8%B6%85%E8%8A%82%E7%82%B9%EF%BC%9A%E7%BB%9F%E4%B8%80%E5%86%85%E5%AD%98%E8%AE%BF%E9%97%AE%E4%B8%8E%E8%B7%A8%E8%8A%82%E7%82%B9%E9%80%9A%E4%BF%A1%5D%0A%20%20%20%20C%20--%3E%20D%5B%E9%9B%86%E7%BE%A4%EF%BC%9AScale-Out%20%E7%BD%91%E7%BB%9C%E3%80%81%E8%B0%83%E5%BA%A6%E4%B8%8E%E5%AD%98%E5%82%A8%5D%0A%20%20%20%20D%20--%3E%20E%5B%E4%B8%9A%E5%8A%A1%E8%B4%9F%E8%BD%BD%EF%BC%9A%E7%9C%9F%E5%AE%9E%E6%A8%A1%E5%9E%8B%E3%80%81%E7%9C%9F%E5%AE%9E%E8%AF%B7%E6%B1%82%E3%80%81SLA%5D%0A%20%20%20%20E%20--%3E%20F%5B%E5%BD%A2%E6%88%90%E6%80%A7%E8%83%BD%E3%80%81%E6%88%90%E6%9C%AC%E3%80%81%E5%8F%AF%E9%9D%A0%E6%80%A7%E8%AF%84%E4%BC%B0%E7%BB%93%E8%AE%BA%5D%0A`})]),fallback:t(()=>[...u[7]||=[o(` Loading... `,-1)]]),_:1})),u[16]||=s(`<p>单独比较 TFLOPS 或 TOPS 容易产生误判。对于大模型业务，必须同时测量算力利用率、内存带宽利用率、通信时间占比、模型吞吐及尾时延。</p><h2 id="_8-术语与指标说明" tabindex="-1">8. 术语与指标说明 <a class="header-anchor" href="#_8-术语与指标说明" aria-label="Permalink to “8. 术语与指标说明”">​</a></h2><div class="vp-table-wrapper"><table tabindex="0"><thead><tr><th>指标/术语</th><th>说明</th></tr></thead><tbody><tr><td>TFLOPS / PFLOPS / EFLOPS</td><td>每秒万亿/千万亿/百亿亿次浮点运算；不同精度下的数值不可直接横向比较。</td></tr><tr><td>TOPS</td><td>每秒万亿次整数或指定类型运算；必须同时说明数据精度和计数方式。</td></tr><tr><td>HBM 带宽</td><td>处理器访问封装内高带宽内存的理论带宽，不等同于 CPU DDR 带宽或网络带宽。</td></tr><tr><td>D2D 带宽</td><td>可能表示 Die-to-Die 封装内部互联，也可能在整机产品中用来描述设备间互联；引用时应明确层级。</td></tr><tr><td>RTT</td><td>Round-Trip Time，往返时延。</td></tr><tr><td>TTFT</td><td>Time To First Token，从请求提交到首个输出 Token 的时间。</td></tr><tr><td>TPOT</td><td>Time Per Output Token，生成阶段平均每个输出 Token 的耗时。</td></tr><tr><td>MFU</td><td>Model FLOPs Utilization，模型实际执行 FLOPs 与理论可用 FLOPs 的比值，用于衡量训练算力利用效率。</td></tr><tr><td>Scale-Up</td><td>在较紧密互联域内扩展计算资源，强调低时延、高带宽和统一资源视图。</td></tr><tr><td>Scale-Out</td><td>通过网络连接更多节点/超节点，强调集群规模和横向扩展能力。</td></tr></tbody></table></div><h2 id="_9-总结" tabindex="-1">9. 总结 <a class="header-anchor" href="#_9-总结" aria-label="Permalink to “9. 总结”">​</a></h2><p>Ascend 910C 是昇腾高性能 AI 计算体系的重要基础。其双 Die 计算封装、128 GB 封装内存、约 3.2 TB/s 内存带宽，以及 Atlas 900 A3 的 384 NPU 超节点能力，使其能够支撑大规模训练与推理任务。910C 的系统性能不仅来自芯片算力，还依赖鲲鹏 CPU、内存、灵衢互联、RDMA 网络、CANN 和 HCCL 等软硬件组件的共同作用。</p><p>Ascend 950 系列则进一步面向不同 AI 负载做架构和产品分化：950PR 更偏向 Prefill 和推荐，950DT 更偏向 Decode 和训练；同时通过更丰富的低精度格式、SIMD/SIMT 双编程模型、强化的向量计算能力和 UB 2.0 互联，提升大模型训练及推理的整体效率。</p><p>对于技术选型，建议从目标模型和业务负载出发，将芯片规格、服务器拓扑、超节点规模、软件适配、散热供电及实际基准测试放在同一评估框架中。不要仅根据单项峰值算力或未经核实的路线图数字做采购决策。</p><h2 id="_10-参考资料" tabindex="-1">10. 参考资料 <a class="header-anchor" href="#_10-参考资料" aria-label="Permalink to “10. 参考资料”">​</a></h2><p>以下资料优先选用华为/华为云/昇腾官方页面；910C 芯片内部结构的补充信息引用公开技术论文。在线资料可能随版本更新，查阅时请核对页面更新时间和适用产品型号。</p><ol><li><strong>华为企业业务：昇腾计算产品总览。</strong> Atlas 产品形态与昇腾计算体系介绍。<br><a href="https://e.huawei.com/cn/products/computing/ascend/" target="_blank" rel="noreferrer">https://e.huawei.com/cn/products/computing/ascend/</a></li><li><strong>华为企业业务：Atlas 900 A3 SuperPoD。</strong> 384 NPU、48 TB 统一编址、FP16 算力、互联带宽、机柜形态及散热规格。<br><a href="https://e.huawei.com/cn/products/computing/ascend/atlas-900-a3-superpod" target="_blank" rel="noreferrer">https://e.huawei.com/cn/products/computing/ascend/atlas-900-a3-superpod</a></li><li><strong>华为：以开创的超节点互联技术，引领 AI 基础设施新范式（2025-09-18）。</strong> 910C 产品演进、950PR/950DT 设计定位、950 路线图与 Atlas 950 规划信息。<br><a href="https://www.huawei.com/cn/news/2025/9/hc-xu-keynote-speech" target="_blank" rel="noreferrer">https://www.huawei.com/cn/news/2025/9/hc-xu-keynote-speech</a></li><li><strong>华为云：Atlas 950 SuperPoD 超节点介绍（页面更新于 2026-10-21）。</strong> 950DT 多 Die 架构、AI 子系统、内存、PCIe、UBoE 和 UB 2.0。<br><a href="https://support.huaweicloud.com/resmgmt-modelarts/resmgmt-a5_0002.html" target="_blank" rel="noreferrer">https://support.huaweicloud.com/resmgmt-modelarts/resmgmt-a5_0002.html</a></li><li><strong>华为云：Atlas 950 SuperPoD 的组网拓扑（页面更新于 2026-11-11）。</strong> 64～1024 NPU 模组组网、计算柜、互联柜和超平面设计。<br><a href="https://support.huaweicloud.com/resmgmt-modelarts/resmgmt-a5_0003.html" target="_blank" rel="noreferrer">https://support.huaweicloud.com/resmgmt-modelarts/resmgmt-a5_0003.html</a></li><li><strong>华为：智启新未来，打造智能世界的硅基黑土地（2026-09-17）。</strong> 910C 超节点部署进展、950 超节点商用状态及昇腾生态进展。<br><a href="https://www.huawei.com/cn/news/2026/9/hc-wang-keynote" target="_blank" rel="noreferrer">https://www.huawei.com/cn/news/2026/9/hc-wang-keynote</a></li><li><strong>Zuo et al., “Serving Large Language Models on Huawei CloudMatrix384”, arXiv:2506.12708v2, 2025-06-18.</strong> 910C 双 Die、AIC/AIV、封装内存、CloudMatrix384 节点和网络平面等技术细节。<br><a href="https://arxiv.org/abs/2506.12708" target="_blank" rel="noreferrer">https://arxiv.org/abs/2506.12708</a></li><li><strong>昇腾社区：HCCL 概述。</strong> HCCL 通信原语、通信算法及 HCCS/RoCE/PCIe 链路支持。<br><a href="https://www.hiascend.com/doc_center/source/zh/canncommercial/81RC1/developmentguide/hccl/hcclug/hcclug_000001.html" target="_blank" rel="noreferrer">https://www.hiascend.com/doc_center/source/zh/canncommercial/81RC1/developmentguide/hccl/hcclug/hcclug_000001.html</a></li><li><strong>昇腾社区：CANN 文档与版本入口。</strong> CANN 最新版本说明、软件安装及开发文档。<br><a href="https://www.hiascend.com/cann/document" target="_blank" rel="noreferrer">https://www.hiascend.com/cann/document</a></li><li><strong>华为：超节点架构创新，开源开放共筑全场景算力底座（2025-09）。</strong> Atlas 350 使用 950PR 的产品信息。<br><a href="https://www.huawei.com/cn/news/2025/9/hc-superpod-innovation" target="_blank" rel="noreferrer">https://www.huawei.com/cn/news/2025/9/hc-superpod-innovation</a></li><li><strong>华为：昇腾 950 超节点真机亮相 2026 世界人工智能大会（2026-07-17）。</strong> 1024 卡展示集群、1 EFLOPS FP8、2 EFLOPS FP4、256 TB 统一编址空间及 RTT 指标。<br><a href="https://www.huawei.com/cn/news/2026/7/atlas-950-superpod" target="_blank" rel="noreferrer">https://www.huawei.com/cn/news/2026/7/atlas-950-superpod</a></li><li><strong>华为：华为云企业级 AI 产品全面落地，做最开放的 Agentic Cloud（2026-09-18）。</strong> 灵衢昇腾 950 智算集群服务商用安排。<br><a href="https://www.huawei.com/cn/news/2026/9/hc-agentic-infra-industry-ai" target="_blank" rel="noreferrer">https://www.huawei.com/cn/news/2026/9/hc-agentic-infra-industry-ai</a></li></ol><hr><p><strong>免责声明：</strong> 本文依据截至 2026 年 11 月 23 日可获得的公开资料整理，目的是介绍硬件架构和系统技术，不构成采购承诺或性能保证。芯片、模组、加速卡、服务器和超节点的规格可能因型号、批次、固件版本及交付配置而异；正式设计、招标、采购和验收应以华为及整机厂商提供的最新正式规格书、兼容性清单和测试报告为准。</p>`,12)])}var p=c(d,[[`render`,f]]);export{u as __pageData,p as default};